// Supabase Edge Function "lifeops-api": the LifeOps server code for the GitHub Pages build.
// See PAGES_DEPLOYMENT.md. server.mjs is generated by `npm run build:pages` (not in git).
import { corsHeaders, createHandler, normalizeAppBase, parseAllowedOrigins, type FetchApp } from "./handler.ts";

const FUNCTION_NAME = "lifeops-api";

function env(name: string): string | undefined {
  const value = Deno.env.get(name);
  return value && value.trim() ? value : undefined;
}

/** Supabase injects SUPABASE_PUBLISHABLE_KEYS / SUPABASE_SECRET_KEYS as JSON objects of named keys. */
function keyFromDictionary(name: string): string | undefined {
  const raw = env(name);
  if (!raw) return undefined;
  try {
    const keys = JSON.parse(raw) as Record<string, unknown>;
    const value = keys.default ?? Object.values(keys)[0];
    return typeof value === "string" && value ? value : undefined;
  } catch {
    return undefined;
  }
}

const allowedOrigins = parseAllowedOrigins(env("LIFEOPS_ALLOWED_ORIGINS") ?? "https://gopalinternship-unibasel.github.io");

/**
 * The bundled server code reads the global `process.env` (and `Buffer`). The server code reads
 * SUPABASE_PUBLISHABLE_KEY and SUPABASE_SECRET_KEY; secret names starting with SUPABASE_ are
 * reserved on Supabase, so these two are derived from what the platform injects. They are written
 * to process.env when the runtime allows it; otherwise the global process gets an env object of
 * its own that holds the function's environment plus the derived values.
 */
async function prepareRuntime(): Promise<void> {
  const nodeProcess = (await import("node:process")).default;
  const { Buffer } = await import("node:buffer");
  const derived: Record<string, string> = {};
  const add = (name: string, value: string | undefined) => {
    if (value) derived[name] = value;
  };
  add("SUPABASE_PUBLISHABLE_KEY", env("SUPABASE_PUBLISHABLE_KEY") ?? keyFromDictionary("SUPABASE_PUBLISHABLE_KEYS") ?? env("SUPABASE_ANON_KEY"));
  add("SUPABASE_SECRET_KEY", env("SUPABASE_SECRET_KEY") ?? keyFromDictionary("SUPABASE_SECRET_KEYS") ?? env("SUPABASE_SERVICE_ROLE_KEY"));
  add("NODE_ENV", env("NODE_ENV") ?? "production");

  let written = true;
  for (const [name, value] of Object.entries(derived)) {
    try {
      nodeProcess.env[name] = value;
    } catch {
      written = false;
    }
    if (nodeProcess.env[name] !== value) written = false;
  }
  const g = globalThis as { process?: unknown; Buffer?: unknown };
  if (written) {
    g.process ??= nodeProcess;
  } else {
    const ownEnv: Record<string, string> = { ...Deno.env.toObject(), ...derived };
    g.process = new Proxy(nodeProcess, {
      get: (target, prop, receiver) => (prop === "env" ? ownEnv : Reflect.get(target, prop, receiver)),
    });
  }
  g.Buffer ??= Buffer;
}

let startupError: string | null = null;
try {
  await prepareRuntime();
} catch (error) {
  startupError = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
  console.error("lifeops-api: start-up failed", error);
}

// Loaded on the first request, after the environment is set up; a literal path so the deploy
// bundler includes it. Deno keeps a failed import failed, so a broken bundle answers 500 until
// Supabase starts a new worker (the error is in the function's logs).
let app: Promise<FetchApp> | undefined;
function loadApp(): Promise<FetchApp> {
  app ??= import("./server.mjs").then((module) => (module.default ?? module) as FetchApp);
  return app;
}

const handler = createHandler({
  functionName: FUNCTION_NAME,
  appBase: normalizeAppBase(env("LIFEOPS_APP_BASE") ?? "lifeops-ai"),
  allowedOrigins,
  loadApp,
});

Deno.serve((request: Request) => {
  if (startupError === null) return handler(request);
  const origin = request.headers.get("origin");
  const headers = origin && allowedOrigins.has(origin) ? corsHeaders(origin) : {};
  return new Response(`lifeops-api could not start: ${startupError}`, { status: 500, headers });
});
